/// <summary>
/// Event handlers for VendInvoiceInfoSubLine table.
/// </summary>
class METVendInvoiceInfoSubLineEventHandler
{
}

Method.Source:
/// <summary>
/// Updates the related VendInvoiceInfoTable GRN status after a VendInvoiceInfoSubLine record is inserted.
/// </summary>
/// <param name="sender">
/// The VendInvoiceInfoSubLine record that triggered the event.
/// </param>
/// <param name="e">
/// Event arguments associated with the insert operation.
/// </param>
[DataEventHandler(tableStr(VendInvoiceInfoSubLine), DataEventType::Inserted)]
public static void VendInvoiceInfoSubLine_onInserted(Common sender, DataEventArgs e)
{
    VendInvoiceInfoSubLine vendInvoiceInfoSubLine = sender as VendInvoiceInfoSubLine;
    VendInvoiceInfoTable   vendInvoiceInfoTable;

    VendInvoiceInfoLine vendInvoiceInfoLine = vendInvoiceInfoLine::findRecId(vendInvoiceInfoSubLine.LineRefRecId);

    if (vendInvoiceInfoLine)
    {
        vendInvoiceInfoTable = vendInvoiceInfoLine.vendInvoiceInfoTable(true);
    }

    if (vendInvoiceInfoTable
        && vendInvoiceInfoTable.METEDIInvoice
        && METVendParameters::find().EnableMetcashMatchingLogic
        && vendInvoiceInfoTable.METEDIGrnStatusValue != METEDIGrnStatus::GRN
        && vendInvoiceInfoSubLine.DocumentId != '')
    {
        ttsbegin;

        vendInvoiceInfoTable.metSetEDIGRNStatus(vendInvoiceInfoSubLine.DocumentId);
        vendInvoiceInfoTable.doUpdate();

        ttscommit;
    }
}
